"""Generated by the NL to Flow Diagram Encoder Pipeline."""

import random as _aj_random

import random

class LRUBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self.items = []
        self.recent = []
        self.access_count = []
        self.counter = 0

    def find_index(self, value):
        index = 0
        for item in self.items:
            if (item == value):
                return index
            index = (index + 1)
        return (-1)

    def find_lru_index(self):
        lru_index = 0
        lru_value = self.recent[0]
        index = 0
        for r in self.recent:
            if (r < lru_value):
                lru_value = r
                lru_index = index
            index = (index + 1)
        return lru_index

    def access(self, value):
        index = self.find_index(value)
        if (index != (-1)):
            self.counter = (self.counter + 1)
            self.recent[index] = self.counter
            self.access_count[index] = (self.access_count[index] + 1)
            access_count_value = self.access_count[index]
            print(f'Accessed: {value}  - Access Count = {access_count_value}')
        else:
            print(f'Access attempted but not found: {value}')

    def add(self, value):
        index = self.find_index(value)
        if (index != (-1)):
            self.counter = (self.counter + 1)
            self.recent[index] = self.counter
            self.access_count[index] = (self.access_count[index] + 1)
            updated_access_count = self.access_count[index]
            print(f'Updated existing item: {value} Access Count = {updated_access_count}')
            return
        if (len(self.items) < self.capacity):
            self.items.append(value)
            self.counter = (self.counter + 1)
            self.recent.append(self.counter)
            self.access_count.append(1)
            print(f'Added: {value}  -  Access Count = 1')
            return
        lru = self.find_lru_index()
        evicted = self.items[lru]
        self.items[lru] = value
        self.counter = (self.counter + 1)
        self.recent[lru] = self.counter
        self.access_count[lru] = 1
        print(f'Evicted: {evicted} -  Added: {value} Access Count = 1')

    def get_items(self):
        return self.items

buf = LRUBuffer(5)

buf.add('A')

buf.add('B')

buf.add('C')

buf.add('D')

buf.add('E')

pool = ['A', 'B', 'C', 'D', 'E', 'F', 'G']

for _ in range(0, 10):
    index = _aj_random.randint(0, (len(pool) - 1))
    value = pool[index]
    buf.access(value)

buf.add('F')

buf.add('G')

final_items = buf.get_items()

print(f'Final buffer: {final_items}')
